#if TEST_BUILD
using System;using System.IO;using System.Linq;using System.Threading.Tasks;using System.Collections.Generic;
internal sealed partial class ControlWindow {
 internal async Task RunNameObserveSmoke(){try{OpenLocalImport();for(int i=0;i<200;i++){await Task.Delay(100);if(importDialog!=null&&importDialog.list.Items.Count>0&&(importOperation==null||!importOperation.Busy)&&!importDialog.TestQueueRunning)break;}Require(importDialog!=null&&importDialog.list.Items.Count>0&&!importDialog.TestQueueRunning,"Candidate scan did not complete");var all=new List<ImportCandidate>();foreach(System.Windows.Forms.ListViewItem row in importDialog.list.Items){var c=(ImportCandidate)row.Tag;all.Add(c);if(c.Id=="401000"){Require(c.Name=="甘雨"&&OfficialNameStore.Valid(c.NameSource,c.Id),"Real candidate official name mismatch");row.Selected=true;row.EnsureVisible();}}importDialog.UpdateSelection();await Task.Delay(100);ClientShot(importDialog,"actual-official-candidate");Common.SaveNew(Path.Combine(Common.Root,"evidence/name-candidate-observation.json"),new{passed=true,candidates=all.Select(c=>new{id=c.Id,name=c.Name,source=c.NameSource,checkState=c.Check==null?null:c.Check.State}).ToArray(),playbackStarted=CurrentRun!=null,userClicked=false});importDialog.Close();importDialog=null;}catch(Exception ex){Common.SaveNew(Path.Combine(Common.Root,"evidence/name-observe-failed.json"),new{error=ex.ToString()});}Close();}
 internal async Task RunNameFlowSmoke(){try{
  var item=library.Doc.Items.Single(x=>x.ResourceId=="401000");Require(item.Name=="本地壁纸 401000","Test must begin with latest placeholder");string selectedId=library.Doc.SelectedId;WallpaperCard[] originalCards=null;
  string empty=Path.Combine(Common.Root,"tests/delayed-cache");Directory.CreateDirectory(empty);File.WriteAllText(Path.Combine(Common.Root,"tests/name-cache-root.txt"),empty);StartNameFlow();await TickOfficialNames();Require(item.Name=="本地壁纸 401000","Missing cache changed title");PresentationTick();originalCards=cards.Controls.Cast<WallpaperCard>().ToArray();
  // A real watcher observes appearance of bounded synthetic official-body fixtures.
  foreach(var path in Directory.GetFiles(Path.Combine(Common.AppRoot,"tests/name-fixtures/delayed")))File.Copy(path,Path.Combine(empty,Path.GetFileName(path)));
  await Task.Delay(2200);Require(nameGeneration>0,"Known-cache watcher didn't observe new files");nameNext=DateTimeOffset.MinValue;await TickOfficialNames();Require(item.Name=="甘雨"&&item.NameSource!=null,"Late cache did not automatically fill existing card");
  Require(library.Doc.SelectedId==selectedId&&cards.Controls.Cast<WallpaperCard>().SequenceEqual(originalCards),"Name refresh rebuilt/reordered cards or changed selection");Require(selected==null||selectedName.Text==selected.Name,"Selected name label stale");
  await ProbeDiscovery();Require(RegisteredNameQueryIds(library.Doc.Items).Length==0,"Automatic candidate discovery scheduled name lookup for an empty/meaningfully named catalog");Require(CurrentRun==null&&Directory.GetDirectories(Session,"run-*").Length==0,"Name refresh started playback");ClientShot(this,"names-auto-filled-home");
  string cfg=Path.Combine(Common.Root,"tests/name-cache-root.txt");File.WriteAllText(cfg,Path.Combine(Common.Root,"tests/missing-cache"));var result=await ImportJob("scan",null,null);var candidates=Common.Json.Deserialize<List<ImportCandidate>>(Common.Json.Serialize(result["candidates"]));var candidate=candidates.Single(x=>x.Id=="401000");Require(candidate.Name=="甘雨"&&candidate.NameSource!=null,"Candidate didn't reuse persistent name");ApplyOfficialNames(candidates);
  var d=new ImportDialog(this){TestSkipInitialScan=true};importDialog=d;d.Show(this);var row=d.TestAddCandidate(candidate);await d.TestRunQueue();candidate=(ImportCandidate)row.Tag;row.Selected=true;d.UpdateSelection();await Task.Delay(100);ClientShot(d,"names-official-candidate");d.Close();importDialog=null;
  var reopened=new WallpaperLibrary();Require(reopened.Doc.Items.Single(x=>x.Id==item.Id).Name=="甘雨","Saved title lost after library restart");
  // Future import uses the same receipt/registration code, in this isolated library only.
  Require(CandidateChecks.Passed(candidate),"Existing candidate prerequisites missing");library.Doc.Items.Remove(item);library.Save();var copied=await ImportJob("copy",candidate,null);bool duplicate;var imported=RegisterImport(importOperation,copied,out duplicate);Require(!duplicate&&imported.Name==candidate.Name&&imported.NameSource.SourceSha256==candidate.NameSource.SourceSha256&&imported.RegisteredSha256==candidate.Check.Sha256,"Imported title/source not retained");
  Require(imported.PreviewConfirmedSha256==null&&imported.DesktopConfirmedSha256==null,"Name import inherited another file confirmation");
  // Closing cancels only the new name task using the pre-existing ImportOperation/Job path.
  nameNext=DateTimeOffset.MinValue;nameStamp=null;var pending=TickOfficialNames();await StopNameFlow();await pending;Require(!nameBusy,"Name job remained busy after cancellation");
  Common.SaveNew(Path.Combine(Common.Root,"evidence/name-flow-result.json"),new{passed=true,delayedCacheWatcher=true,existingCardFilledWithoutImport=true,cardsSameControlsAndOrder=true,selectionPreserved=true,candidateUsesPersistentSource=true,restartWithoutOfficialCache=true,futureIsolatedImportRetainsName=true,automaticCandidatesDoNotScheduleBackgroundNameReads=true,noEligiblePlaceholderJobRemainsIdle=true,playbackStarted=false,userClicked=false,syntheticCacheMetadata=true,realOfficialEvidenceCheckedSeparately="tests/name-core/result.json"});
 }catch(Exception ex){Common.SaveNew(Path.Combine(Common.Root,"evidence/name-flow-failed.json"),new{error=ex.ToString()});}Close();}
}
#endif
